const SNAP_THRESHOLD = 0.2;

const ShapeRenderer: React.FC<{ shape: IShape; isSelected: boolean; onSelect: (e: ThreeEvent<MouseEvent>) => void }> = ({ shape, isSelected, onSelect }) => {
  const position = new THREE.Vector3(...shape.position);
  const rotation = new THREE.Euler(...shape.rotation);
  const scale = new THREE.Vector3(...shape.scale);
  const color = isSelected ? HIGHLIGHT_COLOR : shape.color;

  if (shape.type === 'line') {
    const points = shape.points.map(p => new THREE.Vector3(p.x, p.y, p.z));
    return (
      <group position={position} rotation={rotation} scale={scale} onClick={onSelect}>
        <Line points={points} color={color} lineWidth={isSelected ? 3 : 1} />
      </group>
    );
  }

  if (shape.type === 'text') {
    return (
      <group position={position} rotation={rotation} scale={scale} onClick={onSelect}>
        <Text fontSize={shape.fontSize || 0.5} color={color} anchorX="center" anchorY="middle" rotation={[-Math.PI / 2, 0, 0]}>
          {shape.content || shape.name}
        </Text>
      </group>
    );
  }

  if (shape.type === 'flat' || shape.type === 'solid') {
    // Create geometry from points (projecting to XZ plane)
    const shapePts = shape.points.map(p => new THREE.Vector2(p.x, p.z));
    const threeShape = new THREE.Shape(shapePts);
    const extrudeSettings = { depth: shape.height, bevelEnabled: false };

    return (
      <group position={position} rotation={rotation} scale={scale} onClick={onSelect}>
        <mesh rotation={[-Math.PI / 2, 0, 0]}>
          <extrudeGeometry args={[threeShape, extrudeSettings]} />
          <meshStandardMaterial color={color} transparent opacity={shape.type === 'flat' ? 0.8 : 1} />
        </mesh>
        <lineSegments position={[0, 0, 0]} rotation={[-Math.PI / 2, 0, 0]}>
          <edgesGeometry args={[new THREE.ExtrudeGeometry(threeShape, extrudeSettings)]} />
          <lineBasicMaterial color="black" />
        </lineSegments>
      </group>
    );
  }

  return null;
};

