          color: FLAT_COLOR,
          position: [cx, finalPoints[0].y, cz],
          rotation: [0, 0, 0],
          scale: [1, 1, 1]
        };

        replaceShapes(idsToRemove, [newFace]);
        setDrawPoints([]);
        setMeasurement('已建立平面');
        return;
      }
    }

    const newPoint = { x: point.x, y: point.y, z: point.z };
    const newPointsList = [...drawPoints, newPoint];
    setDrawPoints(newPointsList);

    if (tool === ToolType.DRAW_LINE && drawPoints.length > 0) {
      const prev = drawPoints[drawPoints.length - 1];
      const p1 = new THREE.Vector3(prev.x, prev.y, prev.z);
      const p2 = point;
      const lineId = `line-${Date.now()}-${Math.random()}`;

      const lineShape: IShape = {
        id: lineId,
        layerId: activeLayerId,
        type: 'line',
        name: '直線',
        points: [{ x: 0, y: 0, z: 0 }, { x: p2.x - p1.x, y: p2.y - p1.y, z: p2.z - p1.z }],
        position: [p1.x, p1.y, p1.z],
        rotation: [0, 0, 0],
        scale: [1, 1, 1],
        height: 0,
        color: '#000000'
      };

      addShape(lineShape);
      currentChainIds.current.push(lineId);
      attemptGeometryCut(p1, p2);
    }
  }, [drawPoints, tool, activeLayerId, addShape, replaceShapes, attemptGeometryCut, setMeasurement]);

  const handlePointerDown = (e: ThreeEvent<MouseEvent>) => {
    if (e.button !== 0) return;
    e.stopPropagation();

    if (tool === ToolType.SELECT) {
      selectShape('');
      return;
    }

    if ([ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE].includes(tool)) {
      const point = e.point.clone();
      point.x = Math.round(point.x / SNAP_GRID) * SNAP_GRID;
      point.z = Math.round(point.z / SNAP_GRID) * SNAP_GRID;
      point.y = 0;
      addPoint(point);
    }
  };

  const handlePointerMove = (e: ThreeEvent<MouseEvent>) => {
    const point = e.point.clone();
    point.x = Math.round(point.x / SNAP_GRID) * SNAP_GRID;
    point.z = Math.round(point.z / SNAP_GRID) * SNAP_GRID;
    point.y = 0;
    setHoverPoint(point);

    const displayX = Math.round(e.point.x * 100);
    const displayZ = Math.round(e.point.z * 100);
    setMeasurement(`X: ${displayX}cm, Z: ${displayZ}cm`);
  };

  return (
    <>
      <OrbitControls makeDefault />
      <ambientLight intensity={0.5} />
      <directionalLight position={[10, 20, 10]} intensity={1} castShadow />
      <Grid infiniteGrid fadeDistance={50} sectionSize={1} cellSize={0.1} sectionColor="#9ca3af" cellColor="#e5e7eb" />

      {hoverPoint && tool !== ToolType.SELECT && (
        <mesh position={hoverPoint}>
          <sphereGeometry args={[0.05]} />
          <meshBasicMaterial color="red" />
        </mesh>
      )}

      {shapes.map(shape => {
        const layer = layers.find(l => l.id === shape.layerId);
        if (layer && !layer.visible) return null;
        return (
          <ShapeRenderer
            key={shape.id}
            shape={shape}
            isSelected={selectedIds.includes(shape.id)}
            onSelect={(e) => {
              if (tool === ToolType.SELECT) {
                e.stopPropagation();
                selectShape(shape.id, e.shiftKey);
              }
            }}
          />
        );
      })}

      {tool === ToolType.DRAW_LINE && drawPoints.length > 0 && hoverPoint && (
        <Line
          points={[
            [drawPoints[drawPoints.length - 1].x, drawPoints[drawPoints.length - 1].y, drawPoints[drawPoints.length - 1].z],
            [hoverPoint.x, hoverPoint.y, hoverPoint.z]
          ]}
          color="red"
          dashed
          dashScale={2}
        />
      )}

      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.01, 0]} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove}>
        <planeGeometry args={[100, 100]} />
        <meshBasicMaterial visible={false} />
      </mesh>
    </>
  );
};

