  const [isGizmoDragging, setIsGizmoDragging] = useState(false);

  const setShapeRef = useCallback((id: string, ref: THREE.Group | null) => { shapeRefs.current[id] = ref; }, []);

  const { ppState, handlePointerMove: handlePPMove, handlePointerDown: handlePPDown, handlePointerUp: handlePPUp, isDragging: isPPDragging } = usePushPullManager();
  const { rotateState, handleRotateMove, handleClick: handleRotateClick } = useRotateManager(shapeRefs);
  const { drawPoints, cursorPos: drawCursorPos, setCursorPos: setDrawCursorPos, snapInfo: drawSnapInfo, setSnapInfo: setDrawSnapInfo, isDragging: isDrawDragging, handlePointerDown: handleDrawDown, handlePointerUp: handleDrawUp, handleClick: handleDrawClick, typedInput, guideCreating, drawingNormal, inferenceGuide, setInferenceGuide } = useDrawingManager();

  const isOrbitEnabled = !isGizmoDragging && (
      (tool === ToolType.SELECT && !isShapeDragging) ||
      (tool === ToolType.PUSH_PULL && !isPPDragging) ||
      (tool === ToolType.ROTATE && rotateState.phase !== 'rotating') ||
      (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL && tool !== ToolType.ROTATE && !isDrawDragging)
  );

  const pushPullHandlers = useMemo(() => ({ handlePointerDown: handlePPDown, handlePointerUp: handlePPUp, handlePointerMove: handlePPMove }), [handlePPDown, handlePPUp, handlePPMove]);
  const drawingHandlers = useMemo(() => ({ handlePointerDown: handleDrawDown, handlePointerUp: handleDrawUp, handleClick: handleDrawClick }), [handleDrawDown, handleDrawUp, handleDrawClick]);
